const raw = $input.first().json.items || $input.first().json || [];
const newestFirst = Array.isArray(raw) ? raw : [];
// Unipile returns messages newest-first; reverse to chronological order (oldest -> newest)
const chronological = [...newestFirst].reverse();
// Drop the newest message from the transcript since it's already surfaced separately
// as "message_text" (the latest inbound message) - avoids duplicating it in the prompt
const priorMessages = chronological.slice(0, -1);
const lines = priorMessages.map((m) => {
  const who = m.is_sender ? 'Page' : 'Them';
  return who + ': ' + (m.text || '');
});
const context = lines.length > 0 ? lines.join('\n') : '(No prior messages - this is the start of the conversation.)';
const extract = $('Extract & Normalize Fields').first().json;
return [{
  json: {
    context: context,
    message_text: extract.message_text,
    sender_name: extract.sender_name,
    chat_id: extract.chat_id
  },
  pairedItem: { item: 0 }
}];

